"""FoldX steps."""

from __future__ import annotations

from pydantic import BaseModel

from pps.session import Session


class IngestionSettings(BaseModel):
    """Settings for `ingestion`."""

    foldx_dataset_path: str
    """Path to the FoldX dataset."""
    annotation_path: str
    """Path of the output dataset."""
    plddt_threshold: float = 0.7
    """Plddt threshold to filter amino acids in the structural model."""


def ingestion(session: Session, settings: IngestionSettings) -> None:
    """Step to ingest proteome-wide FoldX dataset generated by the OTAR2081 project.

    Ported from `legacy_gentropy.foldx_ingestion.FoldXIngestionStep`.
    """
    raise NotImplementedError
